  FOREIGN KEY (transfer_id,asset_id,transfer_item_id) REFERENCES transfer_item(transfer_id,asset_id,id);
ALTER TABLE reception ADD UNIQUE KEY uq_reception_transfer_id (transfer_id,id);
ALTER TABLE reception_item ADD COLUMN transfer_id BINARY(16) NULL;
UPDATE reception_item i JOIN reception r ON r.id=i.reception_id SET i.transfer_id=r.transfer_id;
ALTER TABLE reception_item MODIFY transfer_id BINARY(16) NOT NULL,
  ADD CONSTRAINT fk_reception_item_exact_reception FOREIGN KEY (transfer_id,reception_id) REFERENCES reception(transfer_id,id),
  ADD CONSTRAINT fk_reception_item_exact_transfer FOREIGN KEY (transfer_id,transfer_item_id) REFERENCES transfer_item(transfer_id,id),
  ADD UNIQUE KEY uq_reception_item_transfer_item (transfer_item_id,id);
